FIGS = [
 dict(id='IS01', slug='juan-damasceno', name='Juan Damasceno', dates='c. 675–749', img=f'{IMG}/juan-damasceno.jpg', pos='50% 20%',
  role='Monje y sacerdote de Siria-Palestina; Doctor de la Iglesia desde 1890. Escribió bajo dominio musulmán. Es la fuente cristiana más antigua de este pack (siglo VIII).',
  why='Dedica el capítulo 101 de su catálogo de herejías a «los ismaelitas» y llama a su religión «precursora del Anticristo».',
  foot='Citas: De haeresibus, cap. 101 (PG 94, col. 763–765). Griego de Migne, con el latín de Lequien en la columna paralela. Traducción al español mía desde el griego, con el latín de Lequien al lado; no hay traducción inglesa de dominio público que haya leído. Fechas aproximadas.',
  quotes=[
   dict(theme=['H'], es='«Existe también la superstición de los ismaelitas, que extravía a los pueblos y que aún hoy prevalece: [[k:es precursora del Anticristo]]. Desciende de Ismael, el que Agar dio a luz a Abrahán; por eso se les llama agarenos e ismaelitas.»',
        work='Sobre las herejías (De haeresibus), cap. 101', date='c. 743 · griego', ref='De haeresibus, cap. 101 (cap. 100 en la edición de Kotter); PG 94, col. 763',
        trans='Griego de Migne, Patrologia Graeca 94, con el latín de Lequien en columna paralela', url='https://archive.org/details/joannis-damasceni-opera-omnia-quae-exstant-1-pg-94 (PDF p. 472)',
        clar='Así abre Juan el capítulo sobre «los ismaelitas»: llama a su religión «precursora del Anticristo» y la hace descender de Ismael. El griego de Migne imprime «σκεῖα» (forma truncada); el latín de la misma página dice «superstitio» y así lo traduzco.'),
   dict(theme=['M'], es='«[…] llamado Mamed, el cual, tras dar con el Antiguo y el Nuevo Testamento y —según dicen— haber tratado con [[k:un monje arriano]], [[k:fundó una herejía propia]]. Y bajo la apariencia de piedad se ganó a la nación y va divulgando que una Escritura le fue enviada desde el cielo. Después de grabar en su libro unas composiciones dignas de risa, les entrega el culto.»',
        work='Sobre las herejías (De haeresibus), cap. 101', date='c. 743 · griego', ref='De haeresibus, cap. 101; PG 94, col. 765',
        trans='Griego de Migne (PG 94), con el latín de Lequien en columna paralela', url='https://archive.org/details/joannis-damasceni-opera-omnia-quae-exstant-1-pg-94 (PDF p. 473)',
        clar='Es el origen de «Mamed» según Juan: encontró la Biblia, habló con un monje arriano (Juan lo cuenta como lo que se decía, «según dicen») y se inventó su propia herejía y una Escritura «bajada del cielo».'),
   dict(theme=['Q'], es='«Dice que hay un solo Dios, creador de todas las cosas, ni engendrado ni engendrador. Dice que Cristo es la Palabra de Dios y su Espíritu, [[k:pero criatura y siervo]], y que nació sin simiente de María, [[k:la hermana de Moisés y de Aarón]].»',
        work='Sobre las herejías (De haeresibus), cap. 101', date='c. 743 · griego', ref='De haeresibus, cap. 101; PG 94, col. 765',
        trans='Griego de Migne (PG 94), con el latín de Lequien en columna paralela', url='https://archive.org/details/joannis-damasceni-opera-omnia-quae-exstant-1-pg-94 (PDF p. 473)',
        clar='Es el resumen que hace Juan de lo que enseña la secta sobre Cristo: Palabra y Espíritu de Dios, pero solo criatura y siervo, no Hijo. Lo de «hermana de Moisés y de Aarón» es lo que Juan atribuye a esa enseñanza (compárese Corán 19:28, «hermana de Aarón»). Después Juan lo refuta.'),
  ]),
 dict(id='IS02', slug='pedro-venerable', name='Pedro el Venerable', dates='c. 1092–1156', img=f'{IMG}/pedro-venerable.jpg', pos='50% 20%',
  role='Abad de Cluny de 1122 a 1156, cabeza de la mayor congregación monástica de Europa. Encargó la primera traducción latina del Corán (Roberto de Ketton, c. 1143).',
  why='Escribió contra los sarracenos la Summula y una carta sobre su traducción; su tesis de que el Corán sale de fábulas judías y de sandeces de herejes la repitieron autores posteriores (Riccoldo, por ejemplo).',
  foot='Citas: Summula quaedam brevis (PL 189, col. 652–655) y Epistola de translatione sua (PL 189, col. 649–651). Latín de Migne (texto digitalizado de archive.org). Traducción al español mía desde el latín; no hay traducción inglesa de dominio público que haya leído. Fechas aproximadas.',
  quotes=[
   dict(theme=['M'], es='«Así los enseñó el miserabilísimo e impiísimo [[k:Mahoma]], que, negando todos los sacramentos de la piedad cristiana, con los que sobre todo se salvan los hombres, ha entregado ya a casi [[k:la tercera parte del género humano]] —no sabemos por qué juicio de Dios— [[k:al diablo y a la muerte eterna]], con inauditos delirios de fábulas.»',
        work='Summula breve contra la herejía y secta de los sarracenos', date='c. 1143–1155 · latín', ref='Summula quaedam brevis, PL 189, col. 652–653',
        trans='Latín de Migne, Patrologia Latina 189 (texto digitalizado)', url='https://archive.org/details/patrologiaecur189mign',
        clar='Es el juicio de Pedro sobre Mahoma en su resumen de la «secta de los sarracenos»: su enseñanza, con «delirios de fábulas», habría arrastrado a casi un tercio de la humanidad al infierno. «La tercera parte» es su cifra aproximada, no un dato estadístico.'),
   dict(theme=['Q'], es='«Así, instruido por los mejores maestros, judíos y herejes, [[k:Mahoma compuso su Corán]] y, a su manera bárbara, tejió una Escritura nefanda hecha tanto de [[k:fábulas judías]] como de [[k:sandeces de herejes]].»',
        work='Summula breve contra la herejía y secta de los sarracenos', date='c. 1143–1155 · latín', ref='Summula quaedam brevis, PL 189, col. 653–655',
        trans='Latín de Migne (PL 189, texto digitalizado)', url='https://archive.org/details/patrologiaecur189mign',
        clar='Es la tesis de Pedro sobre el origen del Corán: no vino del cielo, sino que Mahoma lo armó con material de judíos y de herejes cristianos. Pedro no da pruebas aquí; la cuenta como explicación de por qué el Corán se parece en parte a la Biblia.'),
   dict(theme=['H'], es='«[…] toda la secta impía y la vida de aquel hombre nefando, y la ley que llamó Alcorán —es decir, «colección de preceptos»— y que persuadió a los hombres más desdichados de que le había sido entregada del cielo por el ángel Gabriel, la pasé también del árabe al latín […]. Quise hacerlo con este error principal, con esta antorcha de todas las herejías, en la que confluyeron los restos de todas las sectas diabólicas surgidas desde la venida misma del Salvador, para que, así como se reconoce que [[k:casi la mitad del orbe está infectada por su peste mortal]], los que lo ignoran reconozcan, al ser descubierta su necedad y su torpeza, [[k:cuán execrable y digno de ser pisoteado]] es.»',
        work='Carta sobre su traducción (a Bernardo de Claraval)', date='c. 1143 · latín', ref='Epistola de translatione sua, PL 189, col. 649–651',
        trans='Latín de Migne (PL 189, texto digitalizado)', url='https://archive.org/details/patrologiaecur189mign',
        clar='Pedro explica por qué mandó traducir el Corán: para que los cristianos conozcan «el error principal» y puedan refutarlo por escrito, como hicieron los Padres con cada herejía. El «pisoteado» es una imagen retórica sobre desacreditar ese error ante el lector.'),
  ]),
 dict(id='IS03', slug='inocencio-iii', name='Inocencio III', dates='1161–1216', img=f'{IMG}/inocencio-iii.jpg', pos='50% 20%',
  role='Papa de 1198 a 1216. Convocó el IV Concilio de Letrán (1215). En 1213 publicó la bula «Quia maior», de convocatoria de cruzada.',
  why='Una sola frase, pero de papa: define a Mahoma en un documento oficial de la Santa Sede.',
  foot='Cita: bula Quia maior, 1213 (Regesta, lib. XVI; PL 216, col. 818). Latín de Migne (texto digitalizado de archive.org). Traducción al español mía desde el latín; no hay traducción inglesa de dominio público que haya leído. Fecha aproximada.',
  quotes=[
   dict(theme=['M'], es='«Pero desde entonces se levantó [[k:un hijo de perdición, el falso profeta Mahoma]], que [[k:por medio de halagos mundanos y placeres carnales]] apartó de la verdad a muchos; y aunque su perfidia ha prevalecido hasta estos tiempos […]»',
        work='Bula «Quia maior» (carta a los fieles de la provincia de Maguncia)', date='abril de 1213 · latín', ref='Regesta, lib. XVI, bula XXVIII (numeración de Migne); PL 216, col. 818',
        trans='Latín de Migne, Patrologia Latina 216 (texto digitalizado)', url='https://archive.org/details/patrologiaecursu0216mign',
        clar='El papa llama a Mahoma «hijo de perdición» y «falso profeta» y explica su éxito por los placeres que ofrecía. La frase está dentro de una bula que convoca a la cruzada; reproduzco solo esta frase sobre Mahoma, no la llamada a las armas que la rodea. Sigue con la idea de que el poder musulmán es una «bestia» cuyo fin se acerca.'),
  ]),
 dict(id='IS04', slug='aquino', name='Santo Tomás de Aquino', dates='1225–1274', img=f'{IMG}/aquino.jpg', pos='50% 15%',
  role='Fraile dominico; Doctor de la Iglesia («Doctor Angélico»). El gran sistematizador de la teología católica.',
  why='En la Summa contra Gentiles (I, 6) contrapone cómo se difundió el cristianismo con cómo, dice, se difundió la ley de Mahoma.',
  foot='Citas: Summa contra Gentiles I, 6 (latín, Marietti 1905; inglés de los Dominicos ingleses, 1923) y Super I Corinthios, cap. 15, lect. 1 (Parma). Traducción al español mía desde el latín, con el inglés de 1923 como apoyo. Fechas aproximadas.',
  quotes=[
   dict(theme=['M'], es='«Los que introdujeron las sectas del error procedieron por el camino contrario, como se ve en [[k:Mahoma]], que atrajo a los pueblos [[k:con promesas de placeres carnales]], a cuyo deseo incita la concupiscencia de la carne. Dio además preceptos conformes a esas promesas, soltando las riendas al placer carnal, y a ellos es fácil que obedezcan los hombres carnales. Tampoco aportó enseñanzas de verdad, salvo las que cualquiera medianamente sabio puede conocer con su ingenio natural; antes bien, [[k:mezcló las verdades que enseñó con muchas fábulas y doctrinas falsísimas]].»',
        work='Suma contra los Gentiles (Summa contra Gentiles), libro I, cap. 6', date='c. 1259–1265 · latín', ref='Summa contra Gentiles I, 6 (párrafo «Hi vero, qui sectas errorum introduxerunt»)',
        trans='Latín: ed. Marietti, 1905. Inglés: English Dominican Fathers, 1923 (dominio público)', url='https://archive.org/details/summacontragenti0000thom · https://archive.org/details/summacontragenti01thomuoft',
        orig='Hi vero, qui sectas errorum introduxerunt, processerunt via contraria, ut patet in Mahumete, qui, carnalium voluptatum promissis, ad quorum desiderium carnalis concupiscentia instigat, populos illexit. Praecepta etiam tradidit promissis conformia, voluptati carnali habenas relaxans, quibus in promptu est a carnalibus hominibus obediri. Documenta etiam veritatis non attulit, nisi quae de facili a quolibet mediocriter sapiente, naturali ingenio, cognosci possint; quin potius vera quae docuit multis fabulis et falsissimis doctrinis immiscuit.',
        clar='Tomás contrapone a los fundadores de sectas con Cristo: aquellos prometen placer, dan normas cómodas y mezclan verdad con fábulas; y pone a Mahoma como ejemplo. Es una afirmación suya, sin citar fuentes árabes ni el Corán.'),
   dict(theme=['S'], es='«Tampoco empleó signos obrados sobrenaturalmente, con los que únicamente se da un testimonio conveniente de la inspiración divina, pues la obra visible, que no puede ser sino divina, muestra que el maestro de la verdad está inspirado invisiblemente; sino que [[k:dijo ser enviado con el poder de las armas]]: [[k:signos que no faltan ni a los ladrones ni a los tiranos]]. […]»',
        work='Suma contra los Gentiles (Summa contra Gentiles), libro I, cap. 6', date='c. 1259–1265 · latín', ref='Summa contra Gentiles I, 6 (mismo párrafo, a continuación)',
        trans='Latín: ed. Marietti, 1905. Inglés: English Dominican Fathers, 1923 (dominio público)', url='https://archive.org/details/summacontragenti0000thom · https://archive.org/details/summacontragenti01thomuoft',
        orig='Signa etiam non adhibuit supernaturaliter facta, quibus solum divinae inspirationi conveniens testimonium adhibetur, dum operatio visibilis, quae non potest esse nisi divina, ostendit doctorem veritatis invisibiliter inspiratum; sed dixit se in armorum potentia missum; quae signa etiam latronibus et tyrannis non desunt.',
        clar='Para Tomás, la prueba de que Dios envía a un profeta son los milagros. De Mahoma dice que no hizo ninguno y que dijo ser enviado «con el poder de las armas», señal que también tienen los ladrones y tiranos. Omito la frase siguiente, donde llama «bestiales» a los primeros seguidores: es un insulto colectivo y no lo presento.'),
   dict(theme=['S'], es='«Pero si se objeta que también la ley de Mahoma ha sido recibida por muchos, hay que decir que no es semejante: porque aquel [[k:los sometió oprimiéndolos y por la fuerza de las armas]]; en cambio los apóstoles, muriendo, ellos mismos condujeron a otros a la fe, y haciendo signos y prodigios. Aquel proponía además ciertas cosas que pertenecen a los deleites y a la lascivia; pero Cristo y los apóstoles, el desprecio de lo terreno.»',
        work='Comentario a la Primera Epístola a los Corintios (Super I ad Corinthios)', date='c. 1259–1265 · latín', ref='Super I Corinthios, cap. 15, lectio 1 (sobre 1 Cor 15,1-11)',
        trans='Latín de la edición de Parma (1852–1873); sin traducción inglesa de dominio público', url='https://archive.org/details/sanctithomaeaqui13thom',
        clar='Tomás responde a una objeción: «también la ley de Mahoma fue aceptada por muchos». Contesta que no es lo mismo: los apóstoles convencieron muriendo y con milagros; Mahoma, «por la fuerza de las armas», y con deleites. Este texto es una «lectura»: según la tradición, apuntes de sus clases.'),
  ]),
 dict(id='IS05', slug='riccoldo', name='Riccoldo da Monte di Croce', dates='c. 1243–1320', img=f'{IMG}/riccoldo.jpg', pos='50% 20%',
  role='Dominico florentino que vivió como misionero en Oriente Próximo y en Bagdad a finales del siglo XIII.',
  why='Escribió una refutación del Corán capítulo a capítulo, tras vivir entre musulmanes; en ella llama a Mahoma «precursor del Anticristo».',
  foot='Citas: Contra legem Sarracenorum, impreso como Propugnaculum fidei (Venecia, 1608). Latín de la edición de 1608, leído en la imagen de la página. Traducción al español mía desde el latín; no hay traducción inglesa de dominio público que haya leído. Fechas aproximadas.',
  quotes=[
   dict(theme=['M'], es='«En este tercer estado, es decir, después de los tiempos del beato Gregorio, en tiempo de Heraclio, se alzó contra la Iglesia de Dios y contra la verdad [[k:un dragón diabólico]] […] llamado Mahoma, que con el consejo y la ayuda de aquel que es mentiroso y padre de la mentira compuso [[k:una ley mentirosísima y nefanda]], como si fuera de la boca de Dios; a la cual ley llamó Alcorán, como «colección de los preceptos de Dios». Este Mahoma [[k:persiguió a la Iglesia de Dios más que todos los que jamás han existido]].»',
        work='Contra la ley de los sarracenos (Propugnaculum fidei), prefacio', date='c. 1300 · latín', ref='Propugnaculum fidei (Venecia, 1608), Prefatio Authoris, p. 2',
        trans='Latín de la edición de Venecia, 1608; sin traducción inglesa de dominio público', url='https://archive.org/details/bub_gb_lMhEuhL-bVEC (PDF p. 48)',
        clar='Así presenta Riccoldo a Mahoma al abrir su obra: un «dragón diabólico» que, con ayuda del diablo, escribió una ley falsa y la hizo pasar por palabra de Dios. En el […] omito una acusación sobre su vida privada, sin fuente.'),
   dict(theme=['M'], es='«Este Mahoma fue [[k:precursor del Anticristo]], que preparó en el mundo el camino al hijo de perdición; camino y modo que, por irracional que sea, quedó patente más arriba, en el capítulo 8. […]»',
        work='Contra la ley de los sarracenos (Propugnaculum fidei), cap. 10', date='c. 1300 · latín', ref='Propugnaculum fidei (Venecia, 1608), cap. X, p. 37',
        trans='Latín de la edición de Venecia, 1608; sin traducción inglesa de dominio público', url='https://archive.org/details/bub_gb_lMhEuhL-bVEC (PDF p. 83)',
        clar='Riccoldo cierra el capítulo sobre la violencia llamando a Mahoma «precursor del Anticristo»: preparó el camino al «hijo de perdición». Del resto del capítulo no reproduzco las frases que hablan de matar.'),
   dict(theme=['Q'], es='«Primero hay que saber cuáles son los errores principales de la ley de los sarracenos […]. Y hay que saber que [[k:las heces de todos los herejes antiguos]], que el diablo había sembrado dispersas entre otros, [[k:las vomitó juntas en Mahoma]]. El propio Mahoma, con Sabelio, [[k:niega la Trinidad]] […]; y así parece que […] el propio Cristo es de otra esencia que Dios, menor que Dios y sometido a él; y en esto coincide con Arrio y Eunomio, que sostenían que Cristo era una pura criatura, aunque excelentísima.»',
        work='Contra la ley de los sarracenos (Propugnaculum fidei), cap. 1', date='c. 1300 · latín', ref='Propugnaculum fidei (Venecia, 1608), cap. I, p. 5',
        trans='Latín de la edición de Venecia, 1608; sin traducción inglesa de dominio público', url='https://archive.org/details/bub_gb_lMhEuhL-bVEC (PDF p. 51)',
        clar='Riccoldo dice que el Islam reúne todas las herejías cristianas antiguas: niega la Trinidad como Sabelio y rebaja a Cristo a criatura como Arrio. La imagen de las «heces» procede de Pedro el Venerable (IS02); la toma y la adapta.'),
  ]),
 dict(id='IS06', slug='dante', name='Dante Alighieri', dates='1265–1321', img=f'{IMG}/dante.jpg', pos='50% 20%',
  role='Poeta florentino, el mayor de la literatura italiana; católico, autor de la Divina Comedia.',
  why='El canto XXVIII del Infierno es una de las imágenes de Mahoma más conocidas de la literatura cristiana medieval.',
  foot='Cita: Divina Comedia, Infierno, XXVIII, vv. 28–39. Italiano de Wikisource (CC BY-SA); inglés de apoyo: Longfellow, 1867 (dominio público). Traducción al español mía (prosificada, verso a verso). Fechas aproximadas.',
  quotes=[
   dict(theme=['M'], es='«Mientras yo me empeñaba en mirarlo entero, / me miró y se abrió el pecho con las manos, / diciendo: «¡Mira cómo me desgarro! / ¡Mira [[k:cómo está mutilado Mahoma]]! / Delante de mí va llorando Alí, / partido el rostro del mentón al copete. / Y todos los demás que ves aquí / [[k:sembradores de escándalo y de cisma]] fueron en vida, y por eso están partidos así. / Un diablo hay aquí detrás que nos taja / con tanta crueldad, al filo de la espada, / volviendo a poner a cada uno de esta tropa […]»',
        work='La Divina Comedia, Infierno, canto XXVIII (octava fosa del círculo octavo)', date='c. 1308–1321 · italiano', ref='Infierno XXVIII, vv. 28–39',
        trans='Italiano: Wikisource (CC BY-SA). Inglés de apoyo: Longfellow, 1867 (dominio público)', url='https://it.wikisource.org/wiki/Divina_Commedia/Inferno/Canto_XXVIII',
        orig='Mentre che tutto in lui veder m’attacco, / guardommi e con le man s’aperse il petto, / dicendo: «Or vedi com’io mi dilacco! / vedi come storpiato è Mäometto! / Dinanzi a me sen va piangendo Alì, / fesso nel volto dal mento al ciuffetto. / E tutti li altri che tu vedi qui, / seminator di scandalo e di scisma / fuor vivi, e però son fessi così. / Un diavolo è qua dietro che n’accisma / sì crudelmente, al taglio de la spada / rimettendo ciascun di questa risma,',
        clar='Dante pone a Mahoma en el infierno, entre los «sembradores de escándalo y de cisma»: su cuerpo aparece abierto en canal, con Alí a su lado. Es poesía, no un argumento: no discute el Corán, pero muestra cómo veía la Cristiandad a Mahoma, como un cismático condenado.'),
  ]),
 dict(id='IS07', slug='cusa', name='Nicolás de Cusa', dates='1401–1464', img=f'{IMG}/cusa.jpg', pos='50% 20%',
  role='Cardenal alemán (1448), obispo de Brixen, teólogo y filósofo.',
  why='Dedicó una obra entera, la Cribratio Alkorani («Cribado del Corán», dedicada a Pío II), a examinar el Corán, y en ella se dirige a Mahoma en segunda persona.',
  foot='Citas: Cribratio Alkorani, libro III (Opera, 1565; digitalización de la Herzog August Bibliothek, Wolfenbüttel). Latín leído en la imagen de la página. Traducción al español mía desde el latín; no hay traducción inglesa de dominio público que haya leído. Fechas aproximadas.',
  quotes=[
   dict(theme=['S'], es='«Pero me has parecido, oh Mahoma, [[k:haber buscado el poder de dominar bajo pretexto de religión]]; pues lo resuelves todo en la espada, y por la espada aspiras, al menos, al tributo. […] ¿Quién no entiende que el fin de tu religión, el celo y el rito de tu ley, tienden solo a esto: [[k:a que domines]]? […] Tu intención no fue otra que ser grande mediante Dios y la religión; nunca creíste verdaderas esas cosas que finges preceptos de Dios, porque no las guardaste.»',
        work='Cribado del Corán (Cribratio Alkorani), libro III, cap. 8', date='c. 1460–1461 · latín', ref='Cribratio Alkorani III, cap. VIII (p. 919 de la ed. de 1565)',
        trans='Latín, Opera de 1565 (HAB Wolfenbüttel); sin traducción inglesa de dominio público', url='http://diglib.hab.de/drucke/413-theol-2f/start.htm?image=01019',
        clar='Cusa le dice a Mahoma que su religión servía sobre todo para dominar: todo se resuelve con la espada, que da el tributo. Es una acusación sobre sus motivos, dirigida a Mahoma en un texto literario; el título del capítulo es «Que el fin de la obra de Mahoma fue su propia exaltación».'),
   dict(theme=['Q'], es='«¿Cómo, pues, puede llamarse ley de Abrahán tu ley, que se llama la de los árabes, si se aparta del Evangelio? […] ¿Qué te hace tan cambiante y vacilante en todo, sino [[k:la ignorancia de Cristo]]? Dices que Jesús, hijo de la virgen María, es el Cristo, y en esto no yerras; pero [[k:qué es Cristo, lo ignoras por completo]].»',
        work='Cribado del Corán (Cribratio Alkorani), libro III, cap. 11', date='c. 1460–1461 · latín', ref='Cribratio Alkorani III, cap. XI (p. 922 de la ed. de 1565)',
        trans='Latín, Opera de 1565 (HAB Wolfenbüttel); sin traducción inglesa de dominio público', url='http://diglib.hab.de/drucke/413-theol-2f/start.htm?image=01022',
        clar='Cusa niega que el Corán sea «la ley de Abrahán»: se aparta del Evangelio. Y le concede a Mahoma que llame a Jesús el Cristo, pero dice que no sabe qué es Cristo. Los dos cortes marcados con […] omiten dos frases de la misma discusión.'),
   dict(theme=['Q'], es='«Considera si Mahoma fue engañado por los judíos que lo asistían, los cuales le persuadían de que María, la madre de Cristo, había sido hermana de Aarón: [[k:pudieron engañarlo en muchas cosas, siendo tan del todo ignorante de las historias de los tiempos]].»',
        work='Cribado del Corán (Cribratio Alkorani), libro III, cap. 17', date='c. 1460–1461 · latín', ref='Cribratio Alkorani III, cap. XVII (p. 928 de la ed. de 1565)',
        trans='Latín, Opera de 1565 (HAB Wolfenbüttel); sin traducción inglesa de dominio público', url='http://diglib.hab.de/drucke/413-theol-2f/start.htm?image=01028',
        clar='Cusa parte de que el Corán llama a María «hermana de Aarón» (compárese Corán 19:28) y concluye que Mahoma fue engañado por informantes judíos y desconocía la historia: si se equivocó en eso, pudo equivocarse en muchas cosas. Es su argumento, sin citar la sura.'),
  ]),
 dict(id='IS08', slug='pio-ii', name='Pío II (Eneas Silvio Piccolomini)', dates='1405–1464', img=f'{IMG}/pio-ii.jpg', pos='50% 20%',
  role='Humanista y papa de 1458 a 1464, tras la caída de Constantinopla (1453).',
  why='Escribió una carta al sultán Mehmed II, conquistador de Constantinopla, en la que le expone por qué, dice, su religión es falsa y le invita a bautizarse.',
  foot='Citas: Epistola ad Mahumetem (incunable; copia de la Biblioteca Nacional de Florencia, en archive.org). Latín leído en la imagen de la página. Traducción al español mía desde el latín; no hay traducción inglesa de dominio público que haya leído. Fecha aproximada.',
  quotes=[
   dict(theme=['Q'], es='«Acuérdate de tu legislador, que afirma que la Ley y los Profetas han sido corrompidos por los judíos y el Evangelio por los cristianos, y que de la verdad del Nuevo o del Antiguo Testamento solo ha quedado cuanto contiene el Alcorán. […] ¡Ojalá tu legislador hubiera sido tan bueno como astuto, tan veraz como ladino, tan justo como inicuo! [[k:Toda su ley es artificiosa y fraudulenta]].»',
        work='Carta a Mehmed II (Epistola ad Mahumetem)', date='c. 1461 · latín', ref='Epistola ad Mahumetem (PDF p. 69 del ejemplar de Florencia)',
        trans='Latín del incunable (BNC Florencia, archive.org); sin traducción inglesa de dominio público', url='https://archive.org/details/ita-bnc-in2-00000500-001 (PDF p. 69)',
        clar='Pío II le dice al sultán que Mahoma enseñó que la Biblia fue falsificada por judíos y cristianos y que solo vale lo que está en el Corán, y que por eso él no cree el testimonio cristiano ni se bautiza. Pío concluye que toda la ley de Mahoma es «artificiosa y fraudulenta». Resume lo que cree que enseña el Corán; no lo cita.'),
   dict(theme=['H'], es='«[…] promete ríos de leche, de miel y de vino, manjares delicados, muchas esposas y concubinas, el trato con vírgenes y [[k:todo lo que la carne reclama]]. […] Tu ley juzga que la vida del hombre ha de desearse para comer y beber: [[k:así como tu legislador fue carnal en este siglo, así pensó que en el futuro hay que atender a la carne]].»',
        work='Carta a Mehmed II (Epistola ad Mahumetem)', date='c. 1461 · latín', ref='Epistola ad Mahumetem (PDF p. 58 del ejemplar de Florencia)',
        trans='Latín del incunable (BNC Florencia, archive.org); sin traducción inglesa de dominio público', url='https://archive.org/details/ita-bnc-in2-00000500-001 (PDF p. 58)',
        clar='Pío II describe el paraíso del Islam como un paraíso del cuerpo (comida, vino, mujeres) y concluye que eso refleja la vida «carnal» de su legislador. Es su lectura y su juicio; no cita versículos. Omito un comentario irónico sobre ese paraíso.'),
   dict(theme=['S'], es='«[…] la nueva ley agradó y en poco tiempo arraigó tanto que fue recibida entre muchos pueblos, naciones y lenguas; [[k:sus cimientos se echaron en el placer]].»',
        work='Carta a Mehmed II (Epistola ad Mahumetem)', date='c. 1461 · latín', ref='Epistola ad Mahumetem (PDF p. 70 del ejemplar de Florencia)',
        trans='Latín del incunable (BNC Florencia, archive.org); sin traducción inglesa de dominio público', url='https://archive.org/details/ita-bnc-in2-00000500-001 (PDF p. 70)',
        clar='Es la explicación de Pío II del éxito del Islam: la nueva ley «agradó» y se extendió rápido porque estaba construida sobre el placer. Omito lo que sigue en la carta sobre el uso de las armas.'),
  ]),
 dict(id='IS09', slug='savonarola', name='Girolamo Savonarola', dates='1452–1498', img=f'{IMG}/savonarola.jpg', pos='50% 20%',
  role='Fraile dominico y predicador en Florencia. Excomulgado por Alejandro VI en 1497 y ejecutado en 1498; escribió el Triumphus crucis como defensa racional de la fe.',
  why='Dedica el capítulo 7 del libro IV a mostrar que «la secta mahometana carece de toda razón».',
  foot='Citas: Triumphus crucis, libro IV, cap. 7. Latín: impreso de Basilea, 1550 (Bibliander; copia digital de Paderborn); inglés de apoyo: J. Procter, The Triumph of the Cross (1901, traducido del italiano; dominio público). Traducción al español mía desde el latín. Fechas aproximadas.',
  quotes=[
   dict(theme=['S'], es='«Pero, consciente de su ignorancia y de su depravación, Mahoma [[k:ordenó con astucia que su religión no se defendiera sino con la espada]], para que lo que no podía defenderse con la razón y la honestidad se decidiera con ímpetu de fiera.»',
        work='El triunfo de la Cruz (Triumphus crucis), libro IV, cap. 7', date='c. 1497 · latín', ref='Triumphus crucis IV, 7 («Mahumetanorum sectam omni ratione carere»)',
        trans='Latín: impreso de Basilea, 1550 (copia digital de Paderborn). Inglés: Procter, 1901 (dominio público)', url='https://digital.ub.uni-paderborn.de/download/pdf/8330527.pdf · https://www.gutenberg.org/ebooks/74508',
        clar='Savonarola afirma que Mahoma ordenó defender su religión solo con la espada porque sabía que con razones no se sostenía. Es su interpretación; no cita ningún versículo. Dejo fuera la frase siguiente del capítulo.'),
   dict(theme=['S'], es='«¡Oh admirable argumento: anteponer Mahoma a Cristo porque [[k:a pueblos rudos y debilitados]], con sus fraudes y promesas, y además con amenazas y con la espada, los apartó de la santísima fe de Cristo y los llevó al placer y a costumbres perdidas!»',
        work='El triunfo de la Cruz (Triumphus crucis), libro IV, cap. 7', date='c. 1497 · latín', ref='Triumphus crucis IV, 7',
        trans='Latín: impreso de Basilea, 1550 (copia digital de Paderborn). Inglés: Procter, 1901 (dominio público)', url='https://digital.ub.uni-paderborn.de/download/pdf/8330527.pdf · https://www.gutenberg.org/ebooks/74508',
        clar='Savonarola responde con ironía al argumento de que el éxito del Islam lo prueba: con ese criterio, el diablo sería mejor que Cristo (aparta de la verdad a muchos más), y los impíos, que atraen más gente que los justos, estarían por encima de ellos. Para él, Mahoma se impuso con engaños, amenazas y espada.'),
   dict(theme=['Q'], es='«Cuán estúpidamente se contradice Mahoma en el Alcorán se ve también en que [[k:confiesa no saber si él y los suyos están en el camino de la salvación]], y que no tiene entre los mortales a nadie que entienda el Alcorán.»',
        work='El triunfo de la Cruz (Triumphus crucis), libro IV, cap. 7', date='c. 1497 · latín', ref='Triumphus crucis IV, 7',
        trans='Latín: impreso de Basilea, 1550 (copia digital de Paderborn). Inglés: Procter, 1901 (dominio público)', url='https://digital.ub.uni-paderborn.de/download/pdf/8330527.pdf · https://www.gutenberg.org/ebooks/74508',
        clar='Savonarola dice que el propio Corán delata a Mahoma: reconoce no saber si está en el camino de la salvación y que nadie lo entiende. Se refiere a pasajes que no cita. La frase siguiente del capítulo es una incitación a apedrear a Mahoma; no la reproduzco.'),
  ]),
 dict(id='IS10', slug='vives', name='Juan Luis Vives', dates='1492–1540', img=f'{IMG}/vives.jpg', pos='50% 20%',
  role='Humanista valenciano (Valencia 1492 – Brujas 1540), amigo de Erasmo y de Tomás Moro; católico.',
  why='En «Sobre la verdad de la fe cristiana» (1543) dedica un libro entero a los «agarenos o mahometanos» y compara a Cristo con Mahoma «según el Alcorán».',
  foot='Citas: De veritate fidei christianae, libro IV (Basilea, 1544; copia de archive.org). Latín leído en la imagen de la página. Traducción al español mía desde el latín; no hay traducción inglesa de dominio público que haya leído. Fechas aproximadas.',
  quotes=[
   dict(theme=['M', 'Q'], es='«Comparemos ahora a Cristo con Mahoma, no según nuestra predicación, sino según el Alcorán y vuestra secta. Cristo, Palabra de Dios; [[k:Mahoma, un mero hombre]]. Cristo, Mesías prometido a los padres y anunciado por un ángel a la virgen excelentísima; Mahoma, oscuro e innoble. […] Cristo, doctor sapientísimo; [[k:Mahoma, del todo ayuno de erudición, sin entender siquiera su propio Alcorán]]. Cristo, seguro de sí y de los suyos; Mahoma, inseguro, como él mismo confiesa en el Alcorán. Cristo vivo —o, como decís vosotros, arrebatado al cielo por Dios; o, como decimos nosotros, devuelto a la vida—; [[k:Mahoma, muerto y putrefacto]].»',
        work='Sobre la verdad de la fe cristiana (De veritate fidei christianae), libro IV', date='1543 · latín', ref='De veritate fidei christianae IV (Basilea, 1544), p. 586',
        trans='Latín del impreso de Basilea, 1544 (archive.org); sin traducción inglesa de dominio público', url='https://archive.org/details/bim_early-english-books-1641-1700_joannes-lodus-viciv_1544',
        clar='Es el discurso de un cristiano a un alfaquí (jurista musulmán) en el diálogo de Vives: Cristo frente a Mahoma, punto por punto. En el […] omito una línea de acusaciones personales sin fuente. «Murió y se pudrió; Cristo vive» es el cierre.'),
   dict(theme=['S'], es='«Si Dios quiere obligar a alguien, ¿qué necesidad tiene de armas? ¿Acaso el que creó y sostiene todas las cosas no puede doblegar y obligar como le plazca? […] Es propio, pues, del Dios que establece su ley [[k:no forzar los cuerpos con la violencia de las armas, sino atraer las almas con milagros y persuasiones]]. Esto hicieron Moisés y Cristo.»',
        work='Sobre la verdad de la fe cristiana (De veritate fidei christianae), libro IV', date='1543 · latín', ref='De veritate fidei christianae IV (Basilea, 1544), p. 576',
        trans='Latín del impreso de Basilea, 1544 (archive.org); sin traducción inglesa de dominio público', url='https://archive.org/details/bim_early-english-books-1641-1700_joannes-lodus-viciv_1544',
        clar='Vives responde a que Mahoma fue enviado «armado y sin milagros»: si Dios hubiera querido obligar, no necesitaría armas. Así queda, para él, descartado que una misión apoyada en las armas venga de Dios. En el […] hay una intervención del interlocutor musulmán.'),
   dict(theme=['Q'], es='«Que Mahoma diga que los hombres no obedecieron a los mensajeros anteriores es [[k:una mentira manifiestísima]]: pues los judíos obedecieron a Moisés, y casi todo el orbe a Cristo, como todavía hoy muchísimos pueblos; y mientras Mahoma vivía, muchas naciones. Dime, ¿cómo podía demostrar más claramente que había sido enviado por Dios que haciendo las obras que solo Dios puede hacer, y que concede únicamente a aquellos a quienes él mismo envía para la salvación de los hombres?»',
        work='Sobre la verdad de la fe cristiana (De veritate fidei christianae), libro IV', date='1543 · latín', ref='De veritate fidei christianae IV (Basilea, 1544), p. 576',
        trans='Latín del impreso de Basilea, 1544 (archive.org); sin traducción inglesa de dominio público', url='https://archive.org/details/bim_early-english-books-1641-1700_joannes-lodus-viciv_1544',
        clar='Vives rechaza la justificación que, según él, da el Corán de la misión armada de Mahoma (los hombres no habrían obedecido a los mensajeros anteriores). Sostiene que Mahoma no hizo ninguno de los milagros que solo Dios puede hacer, así que su misión carece de la prueba que Dios da a sus enviados.'),
  ]),
]
